    keys=['name','type','label','value','optional','help','collection_types','extensions','options']
    d={k:x.get(k) for k in keys if k in x}
    if 'options' in d and isinstance(d['options'], list): d['options']=d['options'][:10]
    print('  '*indent+json.dumps(d, default=str))
    for k in ['cases','inputs']:
